using System.Globalization;

namespace NovaPen;

public static class UiText
{
    public static string Language { get; } = Program.Settings.Language == "system" ? ResolveLanguage(CultureInfo.CurrentUICulture.Name) : Program.Settings.Language;
    internal static string ResolveLanguage(string culture) => culture.Split('-', '_')[0].ToLowerInvariant() switch
    {
        "ru" => "ru", "fr" => "fr", "de" => "de", _ => "en"
    };
    public static string T(string text) => Translate(text, Language);
    internal static string Translate(string text, string language)
    {
        if (!Translations.TryGetValue(text, out var values)) return text;
        return language switch { "ru" => values.Length == 4 ? values[3] : text, "fr" => values[1], "de" => values[2], _ => values[0] };
    }
    public static string F(string text, params object?[] args) => string.Format(CultureInfo.CurrentCulture, T(text), args);
    public static string TrayTooltip => T("NovaPen — показать / скрыть окно");
    public static string ShowWindow => T("Показать окно");
    public static string HideWindow => T("Скрыть окно");
    public static string DrawOnDesktop => T("Рисовать на рабочем столе");
    public static string NewMask => T("Новая маска");
    public static string CloseMask => T("Закрыть маску");
    public static string ExitApp => T("Закрыть программу");
